// ─── Prépare le contexte pour Prompt F ───────────────────────────
const metrics = $('Fetch métriques semaine (DB)').item.json?.data || {};
const templates = $('Fetch templates actifs (DB)').all().map(i => i.json);
const actions = $('Fetch actions semaine (DB)').all().map(i => i.json);

// Calcul des segments qui ont le mieux/moins bien performé
const byTitle = {};
actions.forEach(a => {
  const key = a.title || 'unknown';
  if (!byTitle[key]) byTitle[key] = { total: 0, converted: 0, scores: [] };
  byTitle[key].total++;
  if (['hot_lead','converted'].includes(a.status)) byTitle[key].converted++;
  if (a.conv_score) byTitle[key].scores.push(a.conv_score);
});

const segments = Object.entries(byTitle)
  .filter(([,v]) => v.total >= 3)
  .map(([title, v]) => ({
    title,
    total: v.total,
    converted: v.converted,
    conversion_rate: (v.converted / v.total * 100).toFixed(1) + '%',
    avg_score: v.scores.length ? (v.scores.reduce((a,b) => a+b, 0)/v.scores.length).toFixed(1) : null
  }))
  .sort((a,b) => parseFloat(b.conversion_rate) - parseFloat(a.conversion_rate));

// Identifier templates sous-performants (< 15% response rate et >= 10 envois)
const underperforming = templates.filter(t =>
  t.sends_count >= 10 && (t.response_rate === null || t.response_rate < 15)
);

return [{
  json: {
    week_metrics: metrics,
    templates_performance: templates,
    top_segments: segments.slice(0, 5),
    bottom_segments: segments.slice(-5).reverse(),
    underperforming_templates: underperforming,
    total_actions: actions.length,
    context_json: JSON.stringify({ metrics, templates, segments: segments.slice(0,10), underperforming }, null, 2)
  }
}];

// ─── Parse la réponse Claude et prépare les actions ──────────────
const raw = $input.item.json?.content?.[0]?.text || '';
let insights;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  insights = JSON.parse(match ? match[0] : raw);
} catch(e) {
  throw new Error('[WF6] JSON invalide dans réponse Claude : ' + raw.substring(0, 200));
}

const templateImprovements = insights.template_improvements || [];
const abTestSuggestion = insights.ab_test_suggestion || null;

return [{
  json: {
    insights,
    template_improvements: templateImprovements,
    ab_test_suggestion: abTestSuggestion,
    overall_health: insights.overall_health,
    executive_summary: insights.executive_summary,
    should_create_templates: templateImprovements.length > 0,
    should_create_ab_test: !!abTestSuggestion
  }
}];

// ─── Crée les nouveaux templates améliorés en DB ─────────────────
const improvements = $input.item.json.template_improvements || [];

const queries = improvements
  .filter(t => t.confidence !== 'low' && t.new_system_prompt)
  .map(t => ({
    json: {
      sql: `INSERT INTO message_templates
        (template_type, variant, version, is_active, is_champion, generated_by, system_prompt, user_prompt, model, max_tokens, notes, generation_context)
        SELECT
          '${t.template_type}',
          'A',
          COALESCE((SELECT MAX(version) FROM message_templates WHERE template_type = '${t.template_type}'), 0) + 1,
          TRUE, FALSE,
          'claude_learning',
          '${(t.new_system_prompt || '').replace(/'/g, "''")}',
          '${(t.new_user_prompt || '').replace(/'/g, "''")}',
          'claude-opus-4-7', 500,
          'Auto-amélioré par Learning Loop – ${new Date().toISOString().split('T')[0]}. Attendu : ${(t.expected_improvement || '').replace(/'/g, "''")}',
          '${JSON.stringify({problem: t.problem, confidence: t.confidence}).replace(/'/g, "''")}'
        ON CONFLICT DO NOTHING
        RETURNING id`
    }
  }));

if (queries.length === 0) {
  return [{ json: { skipped: true, reason: 'Aucun template avec confiance suffisante' } }];
}
return queries;

// ─── Discord embed – Rapport hebdomadaire d'apprentissage ──────────
const insights = $('Parse insights Claude').item.json.insights;
const templateCount = $('Parse insights Claude').item.json.template_improvements?.length || 0;

const healthColor = { good: 3066993, warning: 15844367, critical: 15158332 };
const healthEmoji = { good: '✅', warning: '⚠️', critical: '🚨' };
const health = insights.overall_health || 'warning';

const topSegments = (insights.top_performing_segments || []).slice(0,3)
  .map(s => `• **${s.segment}** — ${s.why_it_works}`).join('\n') || '_Aucune donnée_';

const priorities = (insights.next_week_priorities || []).slice(0,3)
  .map((p,i) => `${i+1}. ${p}`).join('\n') || '_Aucune priorité_';

const abTest = insights.ab_test_suggestion;
const abField = abTest ? `\n**Template :** ${abTest.template_type}\n**Hypothèse :** ${abTest.hypothesis}` : '_Aucun test suggéré_';

return [{
  json: {
    embeds: [{
      title: `${healthEmoji[health]} Rapport d'apprentissage hebdomadaire`,
      description: insights.executive_summary || '',
      color: healthColor[health] || 15844367,
      fields: [
        { name: '🏆 Segments qui performent', value: topSegments, inline: false },
        { name: '📈 Diagnostic réponses', value: (insights.response_rate_diagnosis || '').substring(0,200) || '_N/A_', inline: false },
        { name: `🧪 A/B Test suggéré`, value: abField, inline: false },
        { name: '🗓️ Priorités semaine prochaine', value: priorities, inline: false },
        { name: '🤖 Templates améliorés', value: `${templateCount} nouveau(x) template(s) créé(s) par Claude`, inline: true },
        { name: '🏥 Santé système', value: health.toUpperCase(), inline: true }
      ],
      footer: { text: `Learning Loop • ${new Date().toLocaleDateString('fr-FR')}` },
      timestamp: new Date().toISOString()
    }]
  }
}];
